-- StrainX quote comparison — Supabase / Postgres schema.
-- Mirrors backend/app/models.py. Idempotent: safe to run more than once.
-- Run this first, then seed.sql (generated by backend/scripts/gen_seed_sql.py).
--
-- Access: only the FastAPI backend talks to the database, using the service-role key
-- (which bypasses row-level security). RLS is enabled with NO policies, so the public
-- anon key can read or write nothing.

create extension if not exists pgcrypto;  -- gen_random_uuid() (built in on Postgres 13+)

-- Keeps updated_at current on every UPDATE.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Requisitions
-- ---------------------------------------------------------------------------
create table if not exists public.requisitions (
  id                  uuid primary key default gen_random_uuid(),
  pr_number           text not null,
  "date"              date not null default current_date,
  requested_by        text not null default '',
  site                text not null default '',
  item_name           text not null,
  specification       text not null default '',
  required_quantity   numeric not null check (required_quantity > 0),
  unit                text not null default 'kg'
                        check (unit in ('kg', 'g', 'L', 'mL', 'pack', 'drum', 'unit')),
  need_by_date        date not null,
  approved_budget     numeric not null default 0 check (approved_budget >= 0),  -- INR
  coa_mandatory       boolean not null default true,
  require_named_brand boolean not null default false,
  quality_notes       text not null default '',
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Quotes (one supplier offer against a requisition)
-- ---------------------------------------------------------------------------
create table if not exists public.quotes (
  id                     uuid primary key default gen_random_uuid(),
  requisition_id         uuid not null references public.requisitions (id) on delete cascade,
  label                  text not null default '',
  supplier_name          text not null,
  supplier_location      text not null default '',
  source_channel         text not null default 'OTHER'
                           check (source_channel in ('EMAIL', 'WHATSAPP', 'PDF', 'PHONE', 'OTHER')),
  product_description    text not null default '',

  -- Quality
  brand_name             text,
  brand_status           text not null default 'MISSING'
                           check (brand_status in ('VERIFIED', 'NAMED_UNVERIFIED', 'MISSING')),
  coa_status             text not null default 'MISSING_OR_UNCLEAR'
                           check (coa_status in ('EVERY_BATCH', 'ON_REQUEST_OR_CONDITIONAL',
                                                 'WITH_MATERIAL', 'MISSING_OR_UNCLEAR')),

  -- Price
  price                  numeric not null check (price >= 0),
  currency               text not null default 'INR',
  fx_rate_to_inr         numeric not null default 1 check (fx_rate_to_inr > 0),
  pricing_unit           text not null default 'per_unit'
                           check (pricing_unit in ('per_unit', 'per_kg', 'per_pack', 'per_drum')),
  pack_size_value        numeric,
  pack_size_unit         text check (pack_size_unit in ('kg', 'g', 'L', 'mL', 'pack', 'drum', 'unit')),
  drum_size_kg           numeric,
  pricing_basis          text not null default 'UNSPECIFIED'
                           check (pricing_basis in ('EX_WORKS', 'CIF', 'DELIVERED', 'PICKUP', 'UNSPECIFIED')),

  -- Tax (primary + optional alternate reading)
  tax_treatment          text not null default 'UNSPECIFIED'
                           check (tax_treatment in ('EXCLUSIVE_GST', 'INCLUSIVE_GST', 'IMPORT_DUTY_IGST',
                                                    'EXEMPT', 'UNSPECIFIED')),
  gst_rate_pct           numeric not null default 18,
  alt_tax_treatment      text check (alt_tax_treatment in ('EXCLUSIVE_GST', 'INCLUSIVE_GST',
                                                           'IMPORT_DUTY_IGST', 'EXEMPT', 'UNSPECIFIED')),
  alt_gst_rate_pct       numeric,
  customs_duty_pct       numeric not null default 12,
  igst_rate_pct          numeric not null default 18,
  clearance_fee_inr      numeric,  -- null -> engine default
  inland_transport_inr   numeric,  -- null -> engine default

  -- Freight
  freight_cost           numeric default 0,  -- null = unknown ("at actual")
  freight_free_above_inr numeric,

  -- Quantity constraints
  moq_quantity           numeric,
  moq_unit               text check (moq_unit in ('kg', 'g', 'L', 'mL', 'pack', 'drum', 'unit')),

  -- Delivery
  lead_time_min_days     integer,
  lead_time_max_days     integer,
  lead_time_basis        text not null default 'CALENDAR' check (lead_time_basis in ('CALENDAR', 'WORKING')),
  lead_time_starts       text not null default 'PO' check (lead_time_starts in ('PO', 'PAYMENT')),
  transit_days           integer not null default 0,

  -- Payment
  payment_terms          text not null default '',
  advance_pct            numeric not null default 0 check (advance_pct between 0 and 100),
  pre_delivery_pct       numeric not null default 0 check (pre_delivery_pct between 0 and 100),
  credit_days            integer not null default 0,

  -- Validity & provenance
  valid_until            date,
  raw_text               text not null default '',
  contradictions         jsonb not null default '[]'::jsonb,  -- list of strings
  notes                  text not null default '',
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Saved comparison runs (weights + full CompareResult snapshot)
-- ---------------------------------------------------------------------------
create table if not exists public.comparison_runs (
  id                uuid primary key default gen_random_uuid(),
  requisition_id    uuid not null references public.requisitions (id) on delete cascade,
  label             text not null default '',
  weights           jsonb not null,
  reference_date    date not null,
  top_pick_label    text,
  top_pick_supplier text,
  result            jsonb not null,
  created_at        timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Chat history (AI assistant)
-- ---------------------------------------------------------------------------
create table if not exists public.chat_messages (
  id             uuid primary key default gen_random_uuid(),
  requisition_id uuid not null references public.requisitions (id) on delete cascade,
  role           text not null check (role in ('user', 'assistant')),
  content        text not null,
  model          text,  -- Groq model that wrote an assistant message
  created_at     timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------------------
drop trigger if exists requisitions_set_updated_at on public.requisitions;
create trigger requisitions_set_updated_at
  before update on public.requisitions
  for each row execute function public.set_updated_at();

drop trigger if exists quotes_set_updated_at on public.quotes;
create trigger quotes_set_updated_at
  before update on public.quotes
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Indexes (match the API's list queries)
-- ---------------------------------------------------------------------------
create index if not exists requisitions_created_at_idx on public.requisitions (created_at desc);
create index if not exists quotes_requisition_id_idx on public.quotes (requisition_id, label);
create index if not exists comparison_runs_requisition_idx on public.comparison_runs (requisition_id, created_at desc);
create index if not exists comparison_runs_created_at_idx on public.comparison_runs (created_at desc);
create index if not exists chat_messages_requisition_idx on public.chat_messages (requisition_id, created_at);

-- ---------------------------------------------------------------------------
-- Row-level security: on, with no policies (service role only)
-- ---------------------------------------------------------------------------
alter table public.requisitions enable row level security;
alter table public.quotes enable row level security;
alter table public.comparison_runs enable row level security;
alter table public.chat_messages enable row level security;
